/*
 * A039392  Numbers whose base-9 representation has the same nonzero number of
 *          7's and 8's.
 * https://oeis.org/A039392
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the n‑th positive integer whose base‑9 representation *
 *            contains an equal, non‑zero number of digits 7 and 8. The
 *            sequence is * generated by a brute‑force search
 * Range:     u8 n <= 6, u16 n <= 7663, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0)
        return 0;                 /* offset starts at 1, but handle 0 safely */

    idx_t found = 0;              /* how many good numbers have been seen */
    for (idx_t val = 1; ; ++val)  /* iterate all positive integers */
    {
        idx_t x = val;
        unsigned c7 = 0, c8 = 0;
        while (x != 0)
        {
            int d = x % 9;
            if (d == 7)
                ++c7;
            else if (d == 8)
                ++c8;
            x /= 9;
        }
        if (c7 == c8 && c7 > 0)   /* equal, non‑zero count of 7 and 8 */
        {
            ++found;
            if (found == n)
                return (seq_t)val;
        }
    }
}
